export * from './updatecheck.js';
// main — runs one command. The once-a-day "newer version" check starts with
// it and prints its one stderr line (if any) after the command is done
// (updatecheck.js; options.updateCheck stands in for its inputs in tests).
export async function main(argv = process.argv, currentDir = process.cwd(), options = {}) {
  const updateCheck = startUpdateCheck({ argv, ...options.updateCheck });
  try {
    return await runCommand(argv, currentDir);
  } finally {
    await updateCheck.finish();
  }
}

async function runCommand(argv, currentDir) {
  const command = argv[2];
  const { flags, positional } = parseCliArgs(argv.slice(3));

  if (['phase', 'spec', 'doctor', 'deploy', 'status', 'test'].includes(command) && positional[0] !== 'hook' && positional[0] !== 'guard') {
    const warning = guardWarning(currentDir);
    if (warning) console.error(`  ⚠ ${warning}`);
  }


  if (command === 'init') {
    const unknown = rejectUnknownFlags(flags, INIT_FLAG_KEYS, 'init');
    if (unknown !== undefined) return unknown;
    if (flags.wait && flags.key) {
      return usageError('--wait cannot be combined with --key');
    }
    if (flags.key !== undefined && typeof lastValue(flags.key) !== 'string') {
      return usageError('--key requires a value');
    }
    if (flags.app !== undefined && typeof lastValue(flags.app) !== 'string') {
      return usageError('--app requires a value');
    }
    if (flags.import !== undefined && typeof lastValue(flags.import) !== 'string') {
      return usageError('--import requires the folder that holds your app');
    }
    let waitTimeout;
    if (flags.waitTimeout !== undefined) {
      waitTimeout = Number(lastValue(flags.waitTimeout));
      if (!Number.isFinite(waitTimeout) || waitTimeout <= 0) {
        return usageError('--wait-timeout requires a positive number of seconds');
      }
    }

    const json = Boolean(flags.json);
    const yes = Boolean(flags.yes);
    const interactive = Boolean(process.stdin.isTTY && process.stdout.isTTY) && !yes && !json;

    try {
      const result = await init({
        cwd: currentDir,
        targetArg: positional[0],
        deploymentMode: lastValue(flags.mode),
        productType: lastValue(flags.productType),
        recipes: flags.recipe ?? flags.recipes,
        mcp: Boolean(flags.mcp),
        skipInstall: Boolean(flags.skipInstall || flags.noDeps || flags.skipDeps),
        key: lastValue(flags.key),
        app: lastValue(flags.app),
        apiBase: lastValue(flags.apiBase),
        fromLogin: Boolean(flags.fromLogin),
        iAmTheOwner: Boolean(flags.iAmTheOwner),
        sandbox: Boolean(flags.sandbox),
        shortRules: Boolean(flags.shortRules),
        wait: Boolean(flags.wait),
        waitTimeout,
        yes,
        json,
        interactive,
        atTerminal: Boolean(process.stdin.isTTY && process.stdout.isTTY),
        import: lastValue(flags.import),
        verbose: Boolean(flags.verbose),
        askStart: interactive,
      });
      return result.exitCode ?? 0;
    } catch (error) {
      console.error(`  Error: ${error?.message || error}`);
      return 1;
    }
  }

  if (command === 'import') {
    const unknown = rejectUnknownFlags(flags, IMPORT_FLAG_KEYS, 'import');
    if (unknown !== undefined) return unknown;
    const sub = positional[0] || 'scan';
    const result = importCommand(sub, currentDir, {
      item: positional[1],
      take: flags.take,
      keep: flags.keep,
      customerData: flags.customerData === undefined ? undefined : lastValue(flags.customerData),
      ownerReply: flags.ownerReply === undefined ? undefined : lastValue(flags.ownerReply),
    });
    if (flags.json) console.log(JSON.stringify(result.json, null, 2));
    else for (const line of result.output) console.log(line);
    return result.exitCode;
  }

  if (command === 'login') {
    const unknown = rejectUnknownFlags(flags, LOGIN_FLAG_KEYS, 'login');
    if (unknown !== undefined) return unknown;
    if (flags.apiBase !== undefined && typeof lastValue(flags.apiBase) !== 'string') {
      return usageError('--api-base requires a value');
    }
    try {
      if (flags.staging && flags.production) return usageError('choose one of --staging or --production');
      if (flags.start && flags.wait) return usageError('choose one of --start or --wait');
      const target = flags.staging ? 'staging' : flags.production ? 'production' : undefined;
      // Two-step sign-in for AI tools: --start prints the link and exits,
      // --wait waits for the approval.
      if (flags.start) {
        return (await loginStart({ apiBase: lastValue(flags.apiBase), target, json: Boolean(flags.json) })).exitCode;
      }
      if (flags.wait) {
        return (await loginWait({ json: Boolean(flags.json) })).exitCode;
      }
      const result = await login({
        apiBase: lastValue(flags.apiBase),
        target: flags.staging ? 'staging' : flags.production ? 'production' : undefined,
        json: Boolean(flags.json),
        // Real terminal → prompt before opening the browser; piped/non-TTY → just
        // print the link (no prompt to hang on).
        interactive: Boolean(process.stdin.isTTY),
        open: Boolean(flags.open) || agentHost() !== null,
      });
      return result.exitCode;
    } catch (error) {
      console.error(`  Error: ${error?.message || error}`);
      return 1;
    }
  }

  if (command === 'logout') {
    const unknown = rejectUnknownFlags(flags, SESSION_FLAG_KEYS, 'logout');
    if (unknown !== undefined) return unknown;
    try {
      return (await logout({ json: Boolean(flags.json) })).exitCode;
    } catch (error) {
      console.error(`  Error: ${error?.message || error}`);
      return 1;
    }
  }

  if (command === 'whoami') {
    const unknown = rejectUnknownFlags(flags, SESSION_FLAG_KEYS, 'whoami');
    if (unknown !== undefined) return unknown;
    try {
      return whoami({ json: Boolean(flags.json) }).exitCode;
    } catch (error) {
      console.error(`  Error: ${error?.message || error}`);
      return 1;
    }
  }

  // Top-level lifecycle commands — the natural forms. `piezas status`,
  // `piezas logs [n]`, and `piezas undeploy` route into the deploy machinery;
  // "undeploy" is named to teach the boundary: it removes the HOSTING, while
  // the app record (and its keys) live on in the console.
  if (command === 'status' || command === 'logs' || command === 'undeploy') {
    // `piezas undeploy --yes "<app name>"`: the scripted path (CI teardown).
    // It also needs PIEZAS_UNDEPLOY_CONFIRM=<app name> set by the owner, and
    // never runs inside an AI tool (deploy() refuses; the guard too).
    const scriptedName = command === 'undeploy' && flags.yes === true && positional.length === 1 ? positional[0] : undefined;
    const unknown = rejectUnknownFlags(flags, command === 'undeploy' ? new Set([...ENV_FLAG_KEYS, 'yes']) : ENV_FLAG_KEYS, command);
    if (unknown !== undefined) return unknown;
    if (scriptedName === undefined && (command === 'logs' ? positional.length > 1 || (positional[0] !== undefined && !/^\d+$/.test(positional[0])) : positional.length > 0)) {
      return usageError(`unexpected argument "${positional.join(' ')}" for ${command}`);
    }
    try {
      const result = await deploy({
        cwd: currentDir,
        app: lastValue(flags.app),
        appsUrl: lastValue(flags.appsUrl),
        status: command === 'status',
        logs: command === 'logs' ? (positional[0] ?? true) : undefined,
        delete: command === 'undeploy',
        ...(scriptedName !== undefined ? { confirmName: scriptedName } : {}),
        interactive: Boolean(process.stdin.isTTY && process.stdout.isTTY),
      });
      return result.exitCode ?? 0;
    } catch (error) {
      console.error(`  Error: ${error?.message || error}`);
      return 1;
    }
  }

  if (command === 'deploy') {
    const unknown = rejectUnknownFlags(flags, DEPLOY_FLAG_KEYS, 'deploy');
    if (unknown !== undefined) return unknown;
    // Natural subcommand forms: `deploy status|logs|delete` behave like their
    // flags (`deploy logs 300` too). Any OTHER positional is a hard error —
    // a mistyped word must never be silently dropped and escalate into a
    // full deployment.
    const [word, ...restPos] = positional;
    if (word !== undefined) {
      if (word === 'status' && restPos.length === 0) {
        flags.status = true;
      } else if (word === 'delete' && restPos.length === 0) {
        flags.delete = true;
      } else if (word === 'logs' && restPos.length <= 1) {
        flags.logs = restPos[0] ?? true;
      } else {
        return usageError(
          `unexpected argument "${positional.join(' ')}" for deploy — did you mean --${word}?`
        );
      }
    }
    const exclusive = ['status', 'logs', 'delete', 'ownerItems', 'ownerReply'].filter((k) => flags[k]);
    if (exclusive.length > 1) {
      return usageError(`--${exclusive[0]} and --${exclusive[1]} cannot be combined`);
    }
    // `deploy --owner-reply "<their words>"`: with no hooks in this session, the
    // AI relays the owner's answer to the deploy's pause; then the deploy runs.
    if (flags.ownerReply !== undefined) {
      const relayed = relayDeployReply(currentDir, String(lastValue(flags.ownerReply)));
      if (!relayed.ok) {
        console.error(`  ${relayed.error}`);
        return 1;
      }
      for (const note of relayed.notes) console.log(`  (For the AI: ${note})`);
      // "keep trying", "check again": recorded; the AI goes back to its work.
      if (!relayed.goLive) return 0;
    }
    // `deploy --owner-items`: print what piezas_deploy takes as owner_items;
    // nothing is uploaded or asked.
    if (flags.ownerItems) {
      try {
        return deployOwnerItems({ cwd: currentDir, dir: lastValue(flags.dir) }).exitCode;
      } catch (error) {
        console.error(`  Error: ${error?.message || error}`);
        return 1;
      }
    }
    if (flags.env !== undefined && inAiTool()) {
      console.error(`  ${OWNER_ONLY_IN_AI_TEXT}`);
      return 1;
    }
    try {
      const result = await deploy({
        cwd: currentDir,
        app: lastValue(flags.app),
        dir: lastValue(flags.dir),
        cmd: lastValue(flags.cmd),
        appsUrl: lastValue(flags.appsUrl),
        envPairs: flags.env,
        reportButton: flags.reportButton === undefined ? undefined : String(lastValue(flags.reportButton)),
        isolated: Boolean(flags.isolated),
        interactive: Boolean(process.stdin.isTTY && process.stdout.isTTY),
        status: Boolean(flags.status),
        logs: flags.logs !== undefined ? lastValue(flags.logs) : undefined,
        delete: Boolean(flags.delete),
      });
      return result.exitCode ?? 0;
    } catch (error) {
      console.error(`  Error: ${error?.message || error}`);
      return 1;
    }
  }

  if (command === 'reports') {
    const unknown = rejectUnknownFlags(flags, REPORTS_FLAG_KEYS, 'reports');
    if (unknown !== undefined) return unknown;
    // `--done a b,c`: the first id lands in the flag, the rest are positional.
    let done;
    if (flags.done !== undefined) {
      if (flags.save) return usageError('--done cannot be combined with --save');
      done = [flags.done, ...positional].flat().filter((v) => typeof v === 'string');
    } else if (positional.length) {
      return usageError(`unexpected argument "${positional.join(' ')}" for reports (to mark reports fixed: --done <id>)`);
    }
    try {
      const result = await reports({ cwd: currentDir, save: Boolean(flags.save), done });
      if (flags.json) console.log(JSON.stringify(result, null, 2));
      return result.exitCode;
    } catch (error) {
      console.error(`  Error: ${error?.message || error}`);
      return 1;
    }
  }

  if (command === 'unattended') {
    const unknown = rejectUnknownFlags(flags, SESSION_FLAG_KEYS, 'unattended');
    if (unknown !== undefined) return unknown;
    const result = unattendedCmd({ cwd: currentDir, state: positional[0] });
    if (flags.json) console.log(JSON.stringify(result, null, 2));
    return result.exitCode;
  }

  if (command === 'report-button') {
    const unknown = rejectUnknownFlags(flags, SESSION_FLAG_KEYS, 'report-button');
    if (unknown !== undefined) return unknown;
    if (positional[0] === 'add') {
      const added = scaffoldReportButton(currentDir);
      const json = { command: 'report-button add', ...added };
      if (flags.json) console.log(JSON.stringify(json, null, 2));
      else if (!added.applicable) console.log('  This app has no server pages to add the Report a problem button to (it needs a Next.js app with app/layout).');
      else if (!added.wired) {
        console.log(added.created.length
          ? '  Added the Report a problem button files, but the button is not shown on the app\'s pages yet.'
          : '  The Report a problem button is in the app, but it is not shown on the app\'s pages.');
        console.log(`  For the AI: ${added.instruction} (${added.reason}). Details: ${added.todo}`);
      } else if (!added.created.length) console.log('  The Report a problem button is already in the app.');
      else console.log('  Added the Report a problem button.');
      return added.applicable && added.ok ? 0 : 1;
    }
    const result = reportButton({ cwd: currentDir, state: positional[0] });
    if (flags.json) console.log(JSON.stringify(result, null, 2));
    return result.exitCode;
  }

  if (command === 'env') {
    const unknown = rejectUnknownFlags(flags, ENV_FLAG_KEYS, 'env');
    if (unknown !== undefined) return unknown;
    const [action, ...rest] = positional;
    // Setting a value is the owner's, never through an AI tool (whatever
    // spelling got the command past the guard).
    if (action === 'set' && inAiTool()) {
      console.error(`  ${OWNER_ONLY_IN_AI_TEXT}`);
      return 1;
    }
    try {
      const result = await envCmd({
        cwd: currentDir,
        action,
        args: rest,
        app: lastValue(flags.app),
        appsUrl: lastValue(flags.appsUrl),
        allowEmpty: Boolean(flags.allowEmpty),
      });
      return result.exitCode ?? 0;
    } catch (error) {
      console.error(`  Error: ${error?.message || error}`);
      return 1;
    }
  }

  // --- delivery protocol ---------------------------------------------------
  // These commands are the plugin's engine: terse lines on stdout, the verdict
  // in the exit code, hard errors on stderr. No human formatting.
  if (command === 'preview') {
    const unknown = rejectUnknownFlags(flags, PREVIEW_FLAG_KEYS, command);
    if (unknown !== undefined) return unknown;
    const [sub] = positional;
    const url = typeof lastValue(flags.url) === 'string' ? lastValue(flags.url) : undefined;
    let result;
    if (sub === 'shots') {
      const routes = typeof lastValue(flags.routes) === 'string' ? lastValue(flags.routes).split(',').map((r) => r.trim()).filter(Boolean) : undefined;
      result = await previewShots(currentDir, { url, routes });
    } else if (sub === 'clips') {
      result = await previewClips(currentDir, { url });
    } else if (sub === 'open' || sub === 'page') {
      const built = buildShowcase(currentDir, { previewUrl: url });
      if (sub === 'open') openInBrowser(pathToFileURL(built.page).href);
      result = { exitCode: 0, output: [`showcase: ${built.page}`] };
    } else {
      return usageError('preview requires: shots --url <url> [--routes /,/a] | clips [--url <url>] | page | open');
    }
    for (const line of result.output) console.log(line);
    return result.exitCode;
  }

  if (command === 'connect') {
    const unknown = rejectUnknownFlags(flags, CONNECT_FLAG_KEYS, command);
    if (unknown !== undefined) return unknown;
    const result = connectApp(currentDir);
    if (flags.json) console.log(JSON.stringify(result.json, null, 2));
    else for (const line of result.output) console.log(line);
    return result.exitCode;
  }

  if (command === 'phase') {
    const unknown = rejectUnknownFlags(flags, PHASE_FLAG_KEYS, 'phase');
    if (unknown !== undefined) return unknown;
    const [subcommand, ...rest] = positional;
    if (!subcommand) {
      return usageError('phase requires a subcommand: init | status | approve | advance | guard');
    }
    if (rest.length > 0) {
      return usageError(`unexpected argument "${rest.join(' ')}" for phase ${subcommand}`);
    }

    try {
      let result;
      if (subcommand === 'init') {
        result = phaseInit(currentDir);
      } else if (subcommand === 'status') {
        result = phaseStatus(currentDir, { context: Boolean(flags.context) });
      } else if (subcommand === 'approve') {
        const gate = lastValue(flags.gate);
        if (typeof gate !== 'string') return usageError('phase approve requires --gate <name> (v1: mock)');
        const ownerReply = flags.ownerReply === undefined ? undefined : lastValue(flags.ownerReply);
        // Inside an AI tool only the owner's own words, relayed, approve.
        if (inAiTool() && !(typeof ownerReply === 'string' && ownerReply.trim())) {
          console.error(`  ${OWNER_ONLY_IN_AI_TEXT}`);
          return 1;
        }
        result = phaseApprove(currentDir, { gate, ownerReply });
      } else if (subcommand === 'advance') {
        result = phaseAdvance(currentDir);
      } else if (subcommand === 'hook') {
        // Lifecycle hook entry point (Claude Code + Codex): event JSON on stdin.
        let payload = null;
        try {
          payload = JSON.parse(readFileSync(0, 'utf-8'));
        } catch {
          return 0;
        }
        const rulesDir = typeof lastValue(flags.rulesDir) === 'string' ? lastValue(flags.rulesDir) : undefined;
        const cliPath = typeof lastValue(flags.cli) === 'string' ? lastValue(flags.cli) : undefined;
        const out = await phaseHook(payload, { rulesDir, cliPath });
        if (out.stdout) process.stdout.write(`${out.stdout}\n`);
        if (out.stderr) process.stderr.write(`${out.stderr}\n`);
        return out.exitCode;
      } else if (subcommand === 'guard') {
        const tool = lastValue(flags.tool);
        if (typeof tool !== 'string') return usageError('phase guard requires --tool <Write|Edit|Bash>');
        let verdict;
        try {
          verdict = phaseGuard({
            cwd: currentDir,
            tool,
            file: typeof lastValue(flags.file) === 'string' ? lastValue(flags.file) : undefined,
            command: typeof lastValue(flags.command) === 'string' ? lastValue(flags.command) : undefined,
            contentFile: typeof lastValue(flags.contentFile) === 'string' ? lastValue(flags.contentFile) : undefined,
          });
        } catch {
          // A check that cannot run refuses (exit 1 would let the step through).
          verdict = { exitCode: 2, reason: HOOK_FAILED_REASON };
        }
        // PreToolUse semantics: exit 2 blocks the call and hands stderr to the
        // model; anything else lets it through, so allow stays silent.
        if (verdict.exitCode === 2) console.error(verdict.reason || HOOK_FAILED_REASON);
        return verdict.exitCode;
      } else {
        return usageError(`unknown phase subcommand '${subcommand}' (init | status | approve | advance | guard)`);
      }

      if (flags.json) {
        console.log(JSON.stringify(result.json, null, 2));
      } else {
        for (const line of result.output) console.log(line);
      }
      return result.exitCode;
    } catch (error) {
      console.error(`error: ${error?.message || error}`);
      return 1;
    }
  }

  if (command === 'spec') {
    const unknown = rejectUnknownFlags(flags, SPEC_FLAG_KEYS, 'spec');
    if (unknown !== undefined) return unknown;
    const [subcommand, ...rest] = positional;
    if (rest.length > 0) {
      return usageError(`unexpected argument "${rest.join(' ')}" for spec ${subcommand}`);
    }
    // The spec is a project artifact: check it from anywhere inside the project.
    const projectDir = findProjectRoot(currentDir) ?? currentDir;
    if (subcommand === 'check') {
      const result = checkSpec(projectDir);
      if (flags.json) console.log(JSON.stringify(result, null, 2));
      else for (const line of formatSpecCheck(result)) console.log(line);
      return result.ok ? 0 : 1;
    }
    if (subcommand === 'coverage') {
      const result = checkCoverage(projectDir);
      if (flags.json) console.log(JSON.stringify(result, null, 2));
      else for (const line of formatSpecCoverage(result)) console.log(line);
      return result.ok ? 0 : 1;
    }
    return usageError(
      subcommand
        ? `unknown spec subcommand '${subcommand}' (check | coverage)`
        : 'spec requires a subcommand: check | coverage',
    );
  }

  if (command === 'test') {
    const unknown = rejectUnknownFlags(flags, TEST_FLAG_KEYS, 'test');
    if (unknown !== undefined) return unknown;
    if (positional.length > 0) {
      return usageError(`unexpected argument "${positional.join(' ')}" for test`);
    }
    try {
      let result;
      if (flags.setup) {
        const setup = await setupTestApp(currentDir, { env: process.env, quiet: Boolean(flags.json), json: Boolean(flags.json) });
        if (flags.json) console.log(JSON.stringify({ command: 'test --setup', ...setup }, null, 2));
        return setup.ok ? 0 : 1;
      }
      if (flags.ownerReply !== undefined && flags.acceptChange === undefined) {
        return usageError('--owner-reply goes with --accept-change (for example --accept-change S-003 --reason "..." --owner-reply "yes Add a contact")');
      }
      if (flags.acceptChange !== undefined) {
        const id = lastValue(flags.acceptChange);
        if (typeof id !== 'string') return usageError('--accept-change requires a part id (for example --accept-change S-003)');
        const reason = flags.reason === undefined ? '' : String(lastValue(flags.reason));
        const ownerReply = flags.ownerReply === undefined ? undefined : String(lastValue(flags.ownerReply));
        result = await acceptCheckChange(currentDir, { id, reason, ownerReply, env: process.env, interactive: Boolean(process.stdin.isTTY && process.stdout.isTTY) });
      } else {
        result = await runTests(currentDir, { env: process.env });
      }
      if (flags.json) console.log(JSON.stringify(result.json, null, 2));
      else for (const line of result.output) console.log(line);
      return result.exitCode;
    } catch (error) {
      console.error(`error: ${error?.message || error}`);
      return 1;
    }
  }

  if (command === 'quality-scan') {
    const unknown = rejectUnknownFlags(flags, QUALITY_FLAG_KEYS, 'quality-scan');
    if (unknown !== undefined) return unknown;
    const [subcommand, ...rest] = positional;
    // The owner's own choices, typed in their own terminal (never by the AI:
    // the guard refuses these, and here an AI tool's shell is refused too).
    if (['on', 'off', 'before-publishing', 'accept', 'skip'].includes(subcommand)) {
      // Any sign of an AI tool's shell refuses (inAiTool: host variables,
      // the process chain, no terminal); nothing turns that off.
      // The AI may relay the owner's exact words (--owner-reply), as `import
      // choose` does; the record says it was relayed. Without them, only the
      // owner's own terminal.
      const ownerReply = flags.ownerReply === undefined ? undefined : String(lastValue(flags.ownerReply));
      if (!ownerReply && (inAiTool() || !process.stdin.isTTY || !process.stdout.isTTY)) {
        console.error(`  ${QUALITY_OWNER_ONLY_TEXT}`);
        return 1;
      }
      const result = qualityOwnerCommand(subcommand, rest, currentDir, { ownerReply });
      if (flags.json) console.log(JSON.stringify(result.json, null, 2));
      else for (const line of result.output) console.log(`  ${line}`);
      return result.exitCode;
    }
    if (rest.length > 0) return usageError(`unexpected argument "${rest.join(' ')}" for quality-scan ${subcommand}`);
    try {
      const result = qualityScanCommand(subcommand, currentDir, {});
      if (!result) return usageError(`unknown quality-scan subcommand '${subcommand}' (packet | verdict | status | on | off | before-publishing | accept)`);
      if (flags.json) console.log(JSON.stringify(result.json, null, 2));
      else for (const line of result.output) console.log(line);
      return result.exitCode;
    } catch (error) {
      console.error(`error: ${error?.message || error}`);
      return 1;
    }
  }

  if (command === 'doctor') {
    const unknown = rejectUnknownFlags(flags, DOCTOR_FLAG_KEYS, 'doctor');
    if (unknown !== undefined) return unknown;
    const projectDir = positional[0] ? resolve(currentDir, positional[0]) : currentDir;
    const result = await runDoctor(projectDir, { strict: Boolean(flags.strict) });
    if (flags.json) {
      console.log(JSON.stringify(result, null, 2));
    } else {
      console.log(formatDoctorResult(result));
    }
    return result.passed ? 0 : 1;
  }

  if (command) {
    return usageError(`unknown command '${command}'`);
  }
  help();
  return 0;
}

export function isCliEntrypoint() {
  if (!process.argv[1]) return false;
  try {
    return realpathSync(process.argv[1]) === fileURLToPath(import.meta.url);
  } catch {
    return import.meta.url === pathToFileURL(process.argv[1]).href;
  }
}

if (isCliEntrypoint()) {
  main().then(
    (code) => {
      process.exitCode = code;
    },
    (error) => {
      console.error(`  Error: ${error?.message || error}`);
      process.exitCode = 1;
    },
  );
}

